package com.cursorsize;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.TooltipOverlay;

/** Final pass: highlights and menus, then cursor, then readable tooltips. */
public class CursorForegroundOverlay extends Overlay
{
    private final CursorSizeOverlay cursor;
    private final TooltipOverlay tooltips;

    @Inject
    CursorForegroundOverlay(CursorSizeOverlay cursor, TooltipOverlay tooltips)
    {
        this.cursor = cursor;
        this.tooltips = tooltips;
        // TOOLTIP sorts after dynamic and fixed overlays. Lower priority draws last here.
        setPosition(OverlayPosition.TOOLTIP);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(-Float.MAX_VALUE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        return cursor.renderFinal(graphics, () -> tooltips.render(graphics));
    }
}

package com.cursorsize;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;

/** Temporary locator ring drawn below the cursor and tooltips. */
@Singleton
class CursorHighlight
{
    private final Client client;
    private final CursorSizeConfig config;
    private final LongSupplier clock;
    private volatile Long expiresAt;
    private volatile Point cursorCentre = new Point(0, 0);

    @Inject
    CursorHighlight(Client client, CursorSizeConfig config)
    {
        this(client, config, System::nanoTime);
    }

    CursorHighlight(Client client, CursorSizeConfig config, LongSupplier clock)
    {
        this.client = client;
        this.config = config;
        this.clock = clock;
    }

    // Ignore transparent padding, including the padding required by native cursors.
    void setCursorImage(BufferedImage image)
    {
        setCursorImage(image, new java.awt.Point());
    }

    void setCursorImage(BufferedImage image, java.awt.Point hotspot)
    {
        int minX = image == null ? 0 : image.getWidth();
        int minY = image == null ? 0 : image.getHeight();
        int maxX = -1;
        int maxY = -1;
        if (image != null)
        {
            for (int y = 0; y < image.getHeight(); y++)
            {
                for (int x = 0; x < image.getWidth(); x++)
                {
                    if ((image.getRGB(x, y) >>> 24) == 0) { continue; }
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);
                    maxX = Math.max(maxX, x);
                    maxY = Math.max(maxY, y);
                }
            }
        }
        cursorCentre = maxX < 0 ? new Point(0, 0) : new Point((minX + maxX + 1) / 2 - hotspot.x, (minY + maxY + 1) / 2 - hotspot.y);
    }

    void trigger()
    {
        expiresAt = clock.getAsLong() + Math.max(100, Math.min(5000, config.highlightDuration())) * 1_000_000L;
    }

    void clear() { expiresAt = null; }

    boolean isActive()
    {
        Long end = expiresAt;
        return end != null && clock.getAsLong() - end < 0 && client.getGameState() == GameState.LOGGED_IN;
    }

    void render(Graphics2D graphics)
    {
        if (!isActive()) { return; }
        Point mouse = client.getMouseCanvasPosition();
        int width = client.getCanvasWidth();
        int height = client.getCanvasHeight();
        if (mouse.getX() < 0 || mouse.getY() < 0 || mouse.getX() >= width || mouse.getY() >= height) { return; }
        int radius = Math.max(10, Math.min(150, config.highlightRadius()));
        Point centre = cursorCentre;
        int centreX = mouse.getX() + centre.getX();
        int centreY = mouse.getY() + centre.getY();
        Graphics2D ring = (Graphics2D) graphics.create();
        try
        {
            ring.clipRect(0, 0, width, height);
            ring.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            // A dark border keeps the ring visible against bright backgrounds.
            ring.setColor(Color.BLACK);
            ring.setStroke(new BasicStroke(5));
            ring.drawOval(centreX - radius, centreY - radius, radius * 2, radius * 2);
            ring.setColor(config.highlightColor());
            ring.setStroke(new BasicStroke(3));
            ring.drawOval(centreX - radius, centreY - radius, radius * 2, radius * 2);
        }
        finally { ring.dispose(); }
    }
}

package com.cursorsize;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.imageio.stream.MemoryCacheImageInputStream;

final class CursorImages
{
    private CursorImages() {}

    static BufferedImage read(InputStream input) throws IOException
    {
        // Explicit memory cache prevents ImageIO from creating temporary files.
        synchronized (ImageIO.class)
        {
            try (MemoryCacheImageInputStream imageInput = new MemoryCacheImageInputStream(input))
            {
                java.util.Iterator<javax.imageio.ImageReader> readers = ImageIO.getImageReaders(imageInput);
                if (!readers.hasNext()) { throw new IOException("cursor.png is not a supported image"); }
                javax.imageio.ImageReader reader = readers.next();
                try
                {
                    reader.setInput(imageInput);
                    return reader.read(0);
                }
                finally { reader.dispose(); }
            }
        }
    }

    static BufferedImage arrow()
    {
        BufferedImage image = new BufferedImage(24, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            Polygon outline = new Polygon(new int[]{0, 0, 6, 11, 16, 11, 22},
                new int[]{0, 25, 20, 31, 29, 18, 18}, 7);
            g.setColor(Color.WHITE);
            g.fillPolygon(outline);
            g.setColor(Color.BLACK);
            g.drawPolygon(outline);
        }
        finally { g.dispose(); }
        return image;
    }

    static BufferedImage scale(BufferedImage source, int requestedPercent, boolean smooth)
    {
        int percent = Math.max(25, Math.min(400, requestedPercent));
        double ratio = Math.min(percent / 100.0, 512.0 / Math.max(source.getWidth(), source.getHeight()));
        int width = Math.max(1, (int) Math.round(source.getWidth() * ratio));
        int height = Math.max(1, (int) Math.round(source.getHeight() * ratio));
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, smooth
                ? RenderingHints.VALUE_INTERPOLATION_BICUBIC : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(source, 0, 0, width, height, null);
        }
        finally { g.dispose(); }
        return result;
    }

    /** Reflect the image without modifying shared built-in cursor images or losing alpha. */
    static BufferedImage mirror(BufferedImage source, boolean horizontal, boolean vertical)
    {
        if (!horizontal && !vertical) { return source; }
        int width = source.getWidth();
        int height = source.getHeight();
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                result.setRGB(x, y, source.getRGB(horizontal ? width - 1 - x : x,
                    vertical ? height - 1 - y : y));
            }
        }
        return result;
    }

    /** Inward outline: no padding, hotspot shift, or changes to the image's alpha mask. */
    static BufferedImage outline(BufferedImage source, int requestedThickness, Color color)
    {
        int thickness = Math.max(0, Math.min(5, requestedThickness));
        if (thickness == 0) { return source; }
        int width = source.getWidth();
        int height = source.getHeight();
        int[] pixels = source.getRGB(0, 0, width, height, null, 0, width);
        int[] result = pixels.clone();
        int rgb = (color == null ? Color.BLACK : color).getRGB() & 0x00ffffff;
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int index = y * width + x;
                if ((pixels[index] >>> 24) == 0) { continue; }
                boolean edge = false;
                for (int dy = -thickness; dy <= thickness && !edge; dy++)
                {
                    for (int dx = -thickness; dx <= thickness; dx++)
                    {
                        if (dx * dx + dy * dy > thickness * thickness) { continue; }
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx < 0 || ny < 0 || nx >= width || ny >= height
                            || (pixels[ny * width + nx] >>> 24) == 0)
                        {
                            edge = true;
                            break;
                        }
                    }
                }
                if (edge) { result[index] = (pixels[index] & 0xff000000) | rgb; }
            }
        }
        BufferedImage outlined = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        outlined.setRGB(0, 0, width, height, result, 0, width);
        return outlined;
    }

    static int legacyPercentage(BufferedImage source, int pixels)
    {
        int size = Math.max(8, Math.min(128, pixels));
        return Math.max(25, Math.min(400, (int) Math.round(100.0 * size
            / Math.max(source.getWidth(), source.getHeight()))));
    }

    static Point hotspot(BufferedImage image, Dimension canvas, boolean horizontal, boolean vertical)
    {
        double ratio = Math.min(1.0, Math.min((double) canvas.width / image.getWidth(),
            (double) canvas.height / image.getHeight()));
        int width = Math.max(1, (int) Math.round(image.getWidth() * ratio));
        int height = Math.max(1, (int) Math.round(image.getHeight() * ratio));
        return new Point(horizontal ? width - 1 : 0, vertical ? height - 1 : 0);
    }

    // Padding prevents AWT from stretching small images to its native cursor size.
    static BufferedImage fitNativeCanvas(BufferedImage image, Dimension canvas)
    {
        if (canvas.width <= 0 || canvas.height <= 0)
        {
            throw new IllegalArgumentException("Custom cursors are unsupported by this display");
        }
        double ratio = Math.min(1.0, Math.min((double) canvas.width / image.getWidth(),
            (double) canvas.height / image.getHeight()));
        BufferedImage result = new BufferedImage(canvas.width, canvas.height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = result.createGraphics();
        try
        {
            g.drawImage(image, 0, 0, Math.max(1, (int) Math.round(image.getWidth() * ratio)),
                Math.max(1, (int) Math.round(image.getHeight() * ratio)), null);
        }
        finally { g.dispose(); }
        return result;
    }
}

package com.cursorsize;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup(CursorSizeConfig.GROUP)
public interface CursorSizeConfig extends Config
{
    String GROUP = "cursorsize";

    @ConfigSection(name = "Cursor", description = "Choose your cursor style, scale, and smoothing.", position = 0)
    String CURSOR_SECTION = "cursor";

    @ConfigSection(name = "Outline", description = "Make your cursor easier to see with a coloured outline.", position = 1)
    String OUTLINE_SECTION = "outline";

    @ConfigSection(name = "Cursor highlight", description = "Find your cursor with a temporary ring.", position = 2)
    String HIGHLIGHT_SECTION = "highlight";

    @ConfigSection(name = "Advanced", description = "Change the orientation of your cursor image.", position = 3)
    String ADVANCED_SECTION = "advanced";

    @ConfigItem(keyName = "style", name = "Cursor style", description = "Follow Custom Cursor uses the cursor selected in RuneLite's Custom Cursor settings, including custom images and equipped weapons. Keep that plugin disabled.", position = 0, section = CURSOR_SECTION)
    default CursorStyle style() { return CursorStyle.FOLLOW_CUSTOM_CURSOR; }

    @Range(min = 25, max = 400)
    @ConfigItem(keyName = "scalePercent", name = "Cursor scale (%)", description = "25–400%. 100% is the original image size; 200% doubles it. Maximum rendered edge: 512 pixels.", position = 1, section = CURSOR_SECTION)
    default int scalePercent() { return 150; }

    @ConfigItem(keyName = "smooth", name = "Smooth scaling", description = "Smooth image edges; disable for crisp pixel art.", position = 2, section = CURSOR_SECTION)
    default boolean smooth() { return false; }

    @ConfigItem(keyName = "mirrorHorizontal", name = "Mirror horizontally", description = "Flip the cursor image left to right. The click point mirrors with the image.", position = 0, section = ADVANCED_SECTION)
    default boolean mirrorHorizontal() { return false; }

    @ConfigItem(keyName = "mirrorVertical", name = "Mirror vertically", description = "Flip the cursor image top to bottom. The click point mirrors with the image.", position = 1, section = ADVANCED_SECTION)
    default boolean mirrorVertical() { return false; }

    @Range(min = 0, max = 5)
    @ConfigItem(keyName = "outlineThickness", name = "Outline thickness", description = "Outline width in pixels after scaling (0–5). 0 disables it. Drawn inside the visible edge to preserve the click point.", position = 3, section = OUTLINE_SECTION)
    default int outlineThickness() { return 0; }

    @ConfigItem(keyName = "outlineColor", name = "Outline colour", description = "Colour of the cursor outline. Set Outline thickness above 0 to enable it.", position = 4, section = OUTLINE_SECTION)
    default Color outlineColor() { return Color.BLACK; }

    @ConfigItem(keyName = "highlightHotkey", name = "Highlight hotkey", description = "Press to highlight the cursor in the game area while logged in. Unassigned by default.", position = 0, section = HIGHLIGHT_SECTION)
    default Keybind highlightHotkey() { return Keybind.NOT_SET; }

    @ConfigItem(keyName = "highlightColor", name = "Highlight colour", description = "Colour of the locator ring.", position = 1, section = HIGHLIGHT_SECTION)
    default Color highlightColor() { return Color.RED; }

    @Range(min = 10, max = 150)
    @ConfigItem(keyName = "highlightRadius", name = "Ring radius", description = "Distance from the visible cursor centre to the ring in pixels (10-150).", position = 2, section = HIGHLIGHT_SECTION)
    default int highlightRadius() { return 40; }

    @Range(min = 100, max = 5000)
    @ConfigItem(keyName = "highlightDuration", name = "Highlight duration (ms)", description = "Time the ring stays visible (100-5000 milliseconds). Press again to restart the timer.", position = 3, section = HIGHLIGHT_SECTION)
    default int highlightDuration() { return 1000; }
}

package com.cursorsize;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Software fallback for displays whose native cursor size is too small. */
@Singleton
public class CursorSizeOverlay extends Overlay
{
    private final Client client;
    private final CursorHighlight highlight;
    private final TooltipManager tooltipManager;
    private volatile List<Tooltip> deferredTooltips = Collections.emptyList();
    private volatile BufferedImage image;
    private java.awt.Point hotspot = new java.awt.Point();
    private volatile long lastRenderNanos;

    @Inject
    CursorSizeOverlay(Client client, TooltipManager tooltipManager, CursorHighlight highlight)
    {
        this.client = client;
        this.highlight = highlight;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.DYNAMIC);
        // Capture tooltips before their normal pass; the final pass draws them after the cursor.
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Float.MAX_VALUE);
    }

    void setImage(BufferedImage image)
    {
        setImage(image, new java.awt.Point());
    }

    synchronized void setImage(BufferedImage image, java.awt.Point hotspot)
    {
        this.hotspot = new java.awt.Point(hotspot);
        this.image = image;
        lastRenderNanos = 0;
        if (image == null) { deferredTooltips = Collections.emptyList(); }
    }

    boolean isRendering(long now)
    {
        return image != null && lastRenderNanos != 0 && now - lastRenderNanos < 250_000_000L;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if ((image != null || highlight.isActive()) && !tooltipManager.getTooltips().isEmpty())
        {
            List<Tooltip> captured = new ArrayList<>(deferredTooltips);
            captured.addAll(tooltipManager.getTooltips());
            deferredTooltips = captured;
            tooltipManager.clear();
        }
        return null;
    }

    void beginFrame()
    {
        deferredTooltips = Collections.emptyList();
    }

    Dimension renderFinal(Graphics2D graphics, Runnable drawTooltips)
    {
        List<Tooltip> captured = deferredTooltips;
        deferredTooltips = Collections.emptyList();
        try
        {
            highlight.render(graphics);
            return renderCursor(graphics);
        }
        finally
        {
            // Keep tooltip rendering in RuneLite, including components, colours and placement.
            tooltipManager.getTooltips().addAll(0, captured);
            if (!tooltipManager.getTooltips().isEmpty()) { drawTooltips.run(); }
        }
    }

    synchronized Dimension renderCursor(Graphics2D graphics)
    {
        BufferedImage current = image;
        Point mouse = client.getMouseCanvasPosition();
        int x = mouse.getX() - hotspot.x;
        int y = mouse.getY() - hotspot.y;
        if (current != null && mouse.getX() >= 0 && mouse.getY() >= 0
            && mouse.getX() < client.getCanvasWidth() && mouse.getY() < client.getCanvasHeight()
            && graphics.hitClip(x, y, current.getWidth(), current.getHeight()))
        {
            graphics.drawImage(current, x, y, null);
            lastRenderNanos = System.nanoTime();
        }
        return null;
    }
}

package com.cursorsize;

import com.google.inject.Provides;
import java.awt.Dimension;
import java.awt.Cursor;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.io.IOException;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.customcursor.CustomCursor;
import net.runelite.client.plugins.customcursor.CustomCursorConfig;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientUI;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Custom Cursor Plus", internalName = "custom-cursor-plus", description = "Make your cursor bigger or smaller", tags = {"mouse", "accessibility"}, conflicts = {"Custom Cursor"})
public class CursorSizePlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(CursorSizePlugin.class);
    @Inject private ClientUI clientUI;
    @Inject private CursorSizeConfig config;
    @Inject private Client client;
    @Inject private CursorSizeOverlay overlay;
    @Inject private CursorForegroundOverlay foregroundOverlay;
    @Inject private OverlayManager overlayManager;
    @Inject private ConfigManager configManager;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    @Inject private KeyManager keyManager;
    @Inject private CursorHighlight highlight;
    private final HotkeyListener highlightListener = new HotkeyListener(() -> config.highlightHotkey())
    {
        @Override
        public void hotkeyPressed()
        {
            if (active && loggedIn) { highlight.trigger(); }
        }

        @Override
        public void focusLost()
        {
            super.focusLost();
            highlight.clear();
        }
    };
    private volatile boolean active;
    private volatile boolean loggedIn;
    private volatile BufferedImage weaponImage;
    // EDT-owned. Hide the native cursor only after a software frame really drew.
    private Cursor transparentCursor;
    private Cursor nativeCursor;
    private final Timer visibilityTimer = new Timer(50, event -> updateCanvasVisibility());

    @Provides
    CursorSizeConfig provideConfig(ConfigManager manager) { return manager.getConfig(CursorSizeConfig.class); }

    @Override
    protected void startUp()
    {
        highlight.clear();
        active = true;
        keyManager.registerKeyListener(highlightListener);
        loggedIn = client.getGameState() == GameState.LOGGED_IN;
        overlayManager.add(overlay);
        overlayManager.add(foregroundOverlay);
        updateCursor();
        refreshWeapon();
    }

    @Override
    protected void shutDown() throws Exception
    {
        active = false;
        keyManager.unregisterKeyListener(highlightListener);
        highlightListener.focusLost();
        overlayManager.remove(overlay);
        overlayManager.remove(foregroundOverlay);
        if (SwingUtilities.isEventDispatchThread()) { resetCursor(); }
        else { SwingUtilities.invokeAndWait(this::resetCursor); }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        // Highlight settings are read live and do not require rebuilding the cursor image.
        if (CursorSizeConfig.GROUP.equals(event.getGroup()) && event.getKey().startsWith("highlight")) { return; }
        if ((CursorSizeConfig.GROUP.equals(event.getGroup()) || "customcursor".equals(event.getGroup())) && active)
        {
            updateCursor();
            refreshWeapon();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        loggedIn = event.getGameState() == GameState.LOGGED_IN;
        if (!loggedIn) { highlight.clear(); }
        if (active)
        {
            updateCursor();
            refreshWeapon();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (active && event.getContainerId() == InventoryID.WORN) { refreshWeapon(); }
    }

    @Subscribe
    public void onBeforeRender(net.runelite.api.events.BeforeRender event)
    {
        overlay.beginFrame();
    }

    private CustomCursor selectedCursor()
    {
        return config.style().selectedCursor(configManager.getConfig(CustomCursorConfig.class).selectedCursor());
    }

    private void refreshWeapon()
    {
        clientThread.invokeLater(() ->
        {
            if (!active || selectedCursor() != CustomCursor.EQUIPPED_WEAPON) { return true; }
            ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
            Item weapon = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
            weaponImage = weapon == null || weapon.getQuantity() <= 0 ? null : itemManager.getImage(weapon.getId());
            updateCursor();
            return true;
        });
    }

    static boolean useOverlay(boolean loggedIn, BufferedImage image, Dimension nativeSize)
    {
        return loggedIn && (image.getWidth() > nativeSize.width || image.getHeight() > nativeSize.height);
    }

    private void updateCursor()
    {
        SwingUtilities.invokeLater(() ->
        {
            if (!active) { return; }
            try
            {
                CustomCursor selected = selectedCursor();
                BufferedImage source;
                if (selected == CustomCursor.CUSTOM_IMAGE)
                {
                    Filepath imagePath = getPluginDirectory().join("cursor.png");
                    try (InputStream input = imagePath.openInputStream())
                    {
                        source = CursorImages.read(input);
                    }
                    if (source == null) { throw new IOException("cursor.png is not a supported image"); }
                }
                else if (selected == CustomCursor.EQUIPPED_WEAPON)
                {
                    source = weaponImage == null ? CursorImages.arrow() : weaponImage;
                }
                else { source = selected == null ? CursorImages.arrow() : selected.getCursorImage(); }
                int percentage = config.scalePercent();
                // Preserve the old apparent size once, without treating pixel values as percentages.
                if (!"true".equals(configManager.getConfiguration(CursorSizeConfig.GROUP, "percentageMigrated")))
                {
                    String legacy = configManager.getConfiguration(CursorSizeConfig.GROUP, "size");
                    if (legacy != null && (selected != CustomCursor.EQUIPPED_WEAPON || weaponImage != null))
                    {
                        try
                        {
                            // RuneLite writes defaults before startup, so a null check is insufficient.
                            if (percentage == 150) { percentage = CursorImages.legacyPercentage(source, Integer.parseInt(legacy)); }
                            configManager.setConfiguration(CursorSizeConfig.GROUP, "percentageMigrated", true);
                            configManager.setConfiguration(CursorSizeConfig.GROUP, "scalePercent", percentage);
                        }
                        catch (NumberFormatException e)
                        {
                            log.warn("Ignoring invalid legacy cursor size");
                        }
                    }
                }
                BufferedImage scaled = CursorImages.scale(source, percentage, config.smooth());
                scaled = CursorImages.mirror(scaled, config.mirrorHorizontal(), config.mirrorVertical());
                scaled = CursorImages.outline(scaled, config.outlineThickness(), config.outlineColor());
                Dimension nativeSize = Toolkit.getDefaultToolkit().getBestCursorSize(scaled.getWidth(), scaled.getHeight());
                BufferedImage nativeImage = CursorImages.fitNativeCanvas(scaled, nativeSize);
                java.awt.Point nativeHotspot = CursorImages.hotspot(scaled, nativeSize,
                    config.mirrorHorizontal(), config.mirrorVertical());
                java.awt.Point overlayHotspot = CursorImages.hotspot(scaled,
                    new Dimension(scaled.getWidth(), scaled.getHeight()), config.mirrorHorizontal(), config.mirrorVertical());
                clientUI.setCursor(Toolkit.getDefaultToolkit().createCustomCursor(nativeImage, nativeHotspot, "Custom Cursor Plus"));
                boolean software = useOverlay(loggedIn, scaled, nativeSize);
                highlight.setCursorImage(software ? scaled : nativeImage, software ? overlayHotspot : nativeHotspot);
                nativeCursor = clientUI.getDefaultCursor();
                log.info("Custom Cursor Plus: style={}, selected={}, size={}x{}, native={}x{}, loggedIn={}, software={}",
                    config.style(), selected, scaled.getWidth(), scaled.getHeight(), nativeSize.width,
                    nativeSize.height, loggedIn, useOverlay(loggedIn, scaled, nativeSize));
                if (useOverlay(loggedIn, scaled, nativeSize))
                {
                    overlay.setImage(scaled, overlayHotspot);
                    BufferedImage blank = new BufferedImage(nativeSize.width, nativeSize.height, BufferedImage.TYPE_INT_ARGB);
                    transparentCursor = Toolkit.getDefaultToolkit().createCustomCursor(blank,
                        new java.awt.Point(0, 0), "Custom Cursor Plus overlay");
                    client.getCanvas().setCursor(nativeCursor);
                    visibilityTimer.start();
                }
                else
                {
                    visibilityTimer.stop();
                    transparentCursor = null;
                    overlay.setImage(null);
                    client.getCanvas().setCursor(nativeCursor);
                }
            }
            catch (IOException | RuntimeException e)
            {
                log.warn("Unable to apply Custom Cursor Plus; restoring the system cursor", e);
                resetCursor();
            }
        });
    }

    private void resetCursor()
    {
        highlight.setCursorImage(null);
        visibilityTimer.stop();
        transparentCursor = null;
        nativeCursor = null;
        overlay.setImage(null);
        client.getCanvas().setCursor(null);
        clientUI.resetCursor();
    }

    private void updateCanvasVisibility()
    {
        Cursor desired = active && loggedIn && overlay.isRendering(System.nanoTime()) ? transparentCursor : nativeCursor;
        if (client.getCanvas().getCursor() != desired) { client.getCanvas().setCursor(desired); }
    }
}

